def rebalance(questions):
    for i, q in enumerate(questions):
        target = i % 4
        a = q["ans"]
        if a != target:
            q["opts"][a], q["opts"][target] = q["opts"][target], q["opts"][a]
            q["ans"] = target
    return questions


def _validate(name, lessons, questions, want_ch):
    problems = []
    if len(lessons) != want_ch:
        problems.append(f"  {name}: {len(lessons)} lessons (want {want_ch})")
    short = [f"{l['title'][:40]} ({len(l['html'])})" for l in lessons if len(l["html"]) < 2500]
    if short:
        problems.append(f"  {name} below depth: {short}")
    if len(questions) != 35:
        problems.append(f"  {name}: {len(questions)} questions (want 35)")
    for q in questions:
        if len(q["opts"]) != 4 or not (0 <= q["ans"] <= 3):
            problems.append(f"  {name} malformed '{q['q'][:40]}'")
    if "ERPNext" in json.dumps({"l": lessons, "q": questions}):
        problems.append(f"  {name}: ERPNext branding leakage")
    return problems


def main():
    root = os.getcwd()
    with io.open(os.path.join(root, INIT), encoding="utf-8") as f:
        init = f.read()
    with io.open(os.path.join(root, DATA_PATH), encoding="utf-8") as f:
        data = json.load(f)

    if '"3.160.0"' in init:
        print("Already applied. Nothing to do.")
        return
    if '"3.159.0"' not in init:
        sys.exit("ABORT: not at v3.159.0.")
    for k in ("tax_compliance", "dimensions"):
        if k not in data:
            sys.exit(f"ABORT: {k} module not found in data file.")

    problems = _validate("ACC5", LESSONS_A5, QUESTIONS_A5, 10) + _validate("ACC6", LESSONS_A6, QUESTIONS_A6, 9)
    if problems:
        print("ABORT — not clean:")
        print("\n".join(problems))
        sys.exit(1)

    for name, lessons, questions, key, desc in (
        ("ACC 5", LESSONS_A5, QUESTIONS_A5, "tax_compliance",
         "Tax accounting and Nigerian compliance: the custody idea — tax money held, not owned — across the VAT, WHT and payroll compartments; the Nigerian frame with the 2025 reform's working consequences; the monthly VAT position with its two register bridges; WHT as agent and sufferer with the certificate chase; PAYE and the payroll custodies with the tie chain; the six-step filing routine with the zeroing invariant; the compliance calendar and the tax reserve; and the audit evidence posture."),
        ("ACC 6", LESSONS_A6, QUESTIONS_A6, "dimensions",
         "Cost centers and dimensions: one chart, many lenses — the cost center tree designed from the accountability structure, the default cascade and mandatory validation that address every posting, the branch P&L read as contribution before fully-loaded with the close-on-contribution rule, the allocation rules (direct first; written, stable, visible bases), budgets per address with cause-before-comment variance reads, and the second dimension's earning test for service lines and projects."),
    ):
        bank = rebalance(list(questions))
        dist = {c: sum(1 for q in bank if q["ans"] == i) for i, c in enumerate("ABCD")}
        if max(dist.values()) > 10:
            print(f"ABORT — {name} spread failed: {dist}")
            sys.exit(1)
        total = sum(len(l["html"]) for l in lessons)
        print(f"{name} v2: {len(lessons)} chapters ({total:,} chars, min {min(len(l['html']) for l in lessons):,}), bank {len(bank)}, spread {dist}")
        if not CHECK_ONLY:
            data[key]["lessons"] = lessons
            data[key]["questions"] = bank
            data[key]["desc"] = desc

    if CHECK_ONLY:
        print("--check given; no files written.")
        return

    with io.open(os.path.join(root, DATA_PATH), "w", encoding="utf-8") as f:
        json.dump(data, f, indent=1, ensure_ascii=False)
        f.write("\n")
    with io.open(os.path.join(root, INIT), "w", encoding="utf-8") as f:
        f.write(init.replace('"3.159.0"', '"3.160.0"'))
    print("  data: ACCOUNTS 5 + 6 lessons + banks REPLACED (style v2.1)")
    print("wrote __version__ -> 3.160.0")


if __name__ == "__main__":
    main()
